#!/usr/bin/env ruby
require'json';require'fileutils';root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);library=File.join(client,'library');files=Dir.glob(File.join(library,'**/*')).select{|p|File.file?(p)};bytes=files.sum{|p|File.size(p)};ignored=File.read(File.join(client,'.gitignore')).lines.map(&:strip).include?('/library/');report={schemaVersion:1,present:Dir.exist?(library),files:files.length,bytes:bytes,ignoredFromSource:ignored,creatorReimportEvidence:false,verdict:'awaiting-creator-reimport'};out=File.join(root,'docs/generated/creal05-library-cache.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");puts 'CREAL05 AUDITED: Creator clean reimport deferred'
